  .lede {
    font-size: 1.15em;
    color: var(--text);
    line-height: 1.8;
  }

  /* Charts */
  .chart-container {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 24px;
    margin: 24px 0;
    position: relative;
  }
  .chart-container canvas { max-height: 420px; }

  /* Tables */
  .table-wrap {
    overflow-x: auto;
    margin: 20px 0;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.92em;
  }
  th {
    background: var(--surface2);
    color: var(--gold-light);
    text-align: left;
    padding: 12px 16px;
    font-weight: 600;
    font-size: 0.8em;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid var(--gold-dim);
  }
  td {
    padding: 10px 16px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
  }
  tr:hover td { background: rgba(200,169,81,0.04); }
  .rank-badge {
    display: inline-block;
    width: 28px;
    height: 28px;
    line-height: 28px;
    text-align: center;
    border-radius: 50%;
    background: var(--gold-dim);
    color: var(--bg);
    font-weight: 700;
    font-size: 0.85em;
